"""Agent configs: generated by the LLM, validated by code, never auto-activated.
Agent instructions are untrusted: they shape tone/focus, never permissions."""
import re
import uuid

from sqlalchemy import func, select

from app.api.deps import Ctx
from app.core.exceptions import Conflict, NotFound, ValidationFailed
from app.db.models import Agent
from app.providers.llm import get_llm
from app.schemas.assistant import AgentConfig, AgentPatch
from app.services.audit import audit
from app.tools.registry import ALLOWLIST

_SQL = re.compile(
    r"\b(select\s+.+\s+from|insert\s+into|update\s+\w+\s+set|delete\s+from|drop\s+(table|database)|"
    r"alter\s+table|truncate\s+table|union\s+select|exec(ute)?\s*\(|xp_cmdshell)\b|;\s*--|/\*.*\*/",
    re.I | re.S)
_ESCALATION = re.compile(
    r"(skip|bypass|without|ignore|disable)\s+(the\s+)?(confirmation|confirm|permission|permissions|"
    r"approval|rules|audit)|ignore (all |previous |prior )?instructions|act as (an? )?(owner|admin)|"
    r"grant (yourself|admin)|run (shell|code|python|sql)|<script|os\.system|subprocess",
    re.I)


def validate_config(cfg: AgentConfig) -> AgentConfig:
    errors: list[dict] = []
    unknown = sorted(set(cfg.enabled_tools) - ALLOWLIST)
    if unknown:
        errors.append({"field": "enabled_tools", "error": "unknown_tool", "tools": unknown})
    if len(set(cfg.enabled_tools)) != len(cfg.enabled_tools):
        errors.append({"field": "enabled_tools", "error": "duplicate_tool"})
    texts = {"name": cfg.name, "description": cfg.description or "", "instructions": cfg.instructions}
    for i, ks in enumerate(cfg.knowledge_sources):
        texts[f"knowledge_sources[{i}]"] = ks.value
        if ks.type == "url" and not re.match(r"^https://[\w.-]+(/\S*)?$", ks.value):
            errors.append({"field": f"knowledge_sources[{i}]", "error": "invalid_url"})
    for field_name, value in texts.items():
        if _SQL.search(value):
            errors.append({"field": field_name, "error": "sql_like_content"})
        if _ESCALATION.search(value):
            errors.append({"field": field_name, "error": "permission_escalation"})
    if errors:
        raise ValidationFailed("Agent configuration rejected", code="agent_config_invalid",
                               details={"errors": errors})
    return cfg


async def generate(description: str, language: str | None) -> tuple[AgentConfig, str]:
    llm = get_llm()
    cfg = await llm.generate_agent_config(description, language, sorted(ALLOWLIST))
    return validate_config(AgentConfig.model_validate(cfg.model_dump())), llm.name


async def get_agent(ctx: Ctx, agent_id: uuid.UUID) -> Agent:
    a = (await ctx.db.execute(select(Agent).where(Agent.id == agent_id, Agent.business_id == ctx.business_id))
         ).scalar_one_or_none()
    if a is None:
        raise NotFound("Agent not found", code="agent_not_found")
    return a


async def create(ctx: Ctx, cfg: AgentConfig) -> Agent:
    validate_config(cfg)
    a = Agent(business_id=ctx.business_id, name=cfg.name, description=cfg.description, language=cfg.language,
              instructions=cfg.instructions, enabled_tools=list(cfg.enabled_tools),
              knowledge_sources=[k.model_dump() for k in cfg.knowledge_sources], status="draft")
    ctx.db.add(a)
    await ctx.db.flush()
    audit(ctx.db, ctx.business_id, ctx.user_id, "agent.created", entity_type="agent", entity_id=a.id)
    await ctx.db.commit()
    await ctx.db.refresh(a)
    return a


async def list_agents(ctx: Ctx, status: str | None, offset: int, limit: int) -> tuple[list[Agent], int]:
    stmt = select(Agent).where(Agent.business_id == ctx.business_id)
    stmt = stmt.where(Agent.status == status) if status else stmt.where(Agent.status != "archived")
    total = (await ctx.db.execute(select(func.count()).select_from(stmt.subquery()))).scalar_one()
    items = (await ctx.db.execute(stmt.order_by(Agent.created_at.desc()).offset(offset).limit(limit))).scalars().all()
    return list(items), total


def _as_config(a: Agent) -> AgentConfig:
    return AgentConfig.model_validate({"name": a.name, "description": a.description, "language": a.language,
                                       "instructions": a.instructions, "enabled_tools": a.enabled_tools,
                                       "knowledge_sources": a.knowledge_sources})


async def patch(ctx: Ctx, agent_id: uuid.UUID, data: AgentPatch) -> Agent:
    a = await get_agent(ctx, agent_id)
    if a.status == "archived":
        raise Conflict("Archived agents cannot be changed", code="agent_archived")
    fields = data.model_dump(exclude_unset=True)
    merged = _as_config(a).model_dump() | {k: v for k, v in fields.items() if v is not None}
    cfg = validate_config(AgentConfig.model_validate(merged))
    a.name, a.description, a.language = cfg.name, cfg.description, cfg.language
    a.instructions, a.enabled_tools = cfg.instructions, list(cfg.enabled_tools)
    a.knowledge_sources = [k.model_dump() for k in cfg.knowledge_sources]
    a.config_version += 1
    audit(ctx.db, ctx.business_id, ctx.user_id, "agent.updated", entity_type="agent", entity_id=a.id,
          metadata={"fields": ",".join(sorted(fields)), "config_version": a.config_version})
    await ctx.db.commit()
    await ctx.db.refresh(a)
    return a


_STATUS_EVENTS = {"active": "agent.activated", "draft": "agent.deactivated", "archived": "agent.archived"}


async def set_status(ctx: Ctx, agent_id: uuid.UUID, status: str) -> Agent:
    a = await get_agent(ctx, agent_id)
    if a.status == "archived" and status != "archived":
        raise Conflict("Archived agents cannot be changed", code="agent_archived")
    if status == "active":
        validate_config(_as_config(a))  # revalidate before activation
    a.status = status
    audit(ctx.db, ctx.business_id, ctx.user_id, _STATUS_EVENTS[status], entity_type="agent", entity_id=a.id)
    await ctx.db.commit()
    await ctx.db.refresh(a)
    return a
